sir 0.3

software CourseSelection {
  metadata {
    displayName "Course Selection";
    namespace "example.course";
  }
  target {
    language java 21;
    framework spring_boot;
    persistence mybatis_plus;
    database mysql;
    build maven;
    interface rest;
  }
  sources { }
  imports { }
  declarations {
    enum Role { STUDENT, TEACHER, ADMIN }
    entity User persistent {
      identity id: Id generated auto;
      field role: Role default Role.STUDENT;
    }
    use DualTokenLogin {
      account: User;
      name: name;
      password: passwordHash;
    }
    use AccountRegistration {
      account: User;
      name: name;
      password: passwordHash;
      show: [role];
    }
    error BadPage;
    error Forbidden http 403;
    input PageOnly {
      field page: PageNo;
      field size: PageSize;
    }

    entity Course persistent {
      identity id: Id generated auto;
      field code: Code unique;
      field name: Name;
      field teacher: Ref<User>;
      field capacity: Quantity;
      field enrolled: Count default 0;
      field weekday: Quantity where max(7);
      field startPeriod: Quantity where max(12);
      field endPeriod: Quantity where max(13);
      field published: Flag default false;
    }
    entity Enrollment persistent {
      identity id: Id generated auto;
      field student: Ref<User>;
      field course: Ref<Course>;
      field createdAt: Moment default now();
      unique (student, course);
    }
    entity Prerequisite persistent {
      identity id: Id generated auto;
      field targetCourse: Ref<Course>;
      field required: Ref<Course>;
      unique (targetCourse, required);
    }
    entity CompletedCourse persistent {
      identity id: Id generated auto;
      field student: Ref<User>;
      field course: Ref<Course>;
      field completedAt: Moment default now();
      unique (student, course);
    }
    view CourseView from Course {
      field id: Id;
      field code: Code;
      field name: Name;
      field teacher: UserView;
      field capacity: Quantity;
      field enrolled: Count;
      field remaining: Count = item.capacity - item.enrolled;
      field full: Flag = item.enrolled >= item.capacity;
      field weekday: Quantity;
      field startPeriod: Quantity;
      field endPeriod: Quantity;
      field published: Flag;
    }
    view EnrollmentView from Enrollment {
      field id: Id;
      field course: CourseView;
      field createdAt: Moment;
    }

    error InvalidSchedule http 400;
    error TeacherNotFound http 404;
    input CourseSearch {
      field keyword: Text;
      field page: PageNo;
      field size: PageSize;
    }
    capability SearchCourses {
      input CourseSearch;
      output Page<CourseView>;
      fails BadPage;
      requires readonly;
      expose query at "/courses";
      workflow {
        find Course
          where item.published == true and (item.name containsLiteral input.keyword or item.code containsLiteral input.keyword)
          order by code ascending, id ascending
          Page input.page, input.size else BadPage
        as rows;
        return rows;
      }
    }

    input CourseRef {
      field id: Id;
    }
    error AlreadyEnrolled http 409;
    error CourseFull http 409;
    error CourseNotFound http 404;
    error CourseNotOpen http 409;
    error CoursePublished http 409;
    error InvalidPrerequisite http 400;
    error MissingPrerequisites http 409;
    error StudentNotFound http 404;
    error TimeConflict http 409;
    error EnrollmentCounterMismatch http 409;
    error PrerequisiteExists http 409;
    error PrerequisiteNotFound http 404;
    error CompletionExists http 409;
    // The seat is taken by one statement that checks the room left and adds one, so two students taking the last seat
    // at the same moment cannot both succeed. A student cannot enrol twice: the pair is unique.
    capability Enroll {
      actor Ref<User>;
      input CourseRef;
      output EnrollmentView;
      fails AlreadyEnrolled;
      fails CourseFull;
      fails CourseNotFound;
      fails CourseNotOpen;
      fails MissingPrerequisites;
      fails StudentNotFound;
      fails TimeConflict;
      requires authenticated;
      requires atomic;
      expose command at "/courses/{id}/enroll";
      workflow {
        // The student is the common serialization point, even for two different target courses.
        load User by actor as learner for update else StudentNotFound;
        load Course by input.id as selected for update else CourseNotFound;
        validate selected.published == true else CourseNotOpen;
        exists Enrollment where item.student == actor and item.course == selected as already;
        validate not already else AlreadyEnrolled;
        exists Course where item.weekday == selected.weekday
          and item.startPeriod < selected.endPeriod and item.endPeriod > selected.startPeriod
          and any(Enrollment, course == item and student == actor) as clashes;
        validate not clashes else TimeConflict;
        exists Course where any(Prerequisite, required == item and targetCourse == selected)
          and not any(CompletedCourse, course == item and student == actor) as missing;
        validate not missing else MissingPrerequisites;
        update selected when selected.enrolled < selected.capacity else CourseFull {
          enrolled: selected.enrolled + 1;
        }
        create Enrollment as made {
          student: actor;
          course: selected;
        }
        persist selected;
        persist made else AlreadyEnrolled;
        return made;
      }
    }
    input EnrollmentRef {
      field id: Id;
    }
    error EnrollmentNotFound http 404;
    // Dropping takes the enrolment away, so the student can enrol again later.
    capability Drop {
      actor Ref<User>;
      input EnrollmentRef;
      output Unit;
      fails CourseNotFound;
      fails EnrollmentCounterMismatch;
      fails EnrollmentNotFound;
      fails Forbidden;
      fails StudentNotFound;
      requires authenticated;
      requires atomic;
      expose command delete at "/enrollments/{id}";
      workflow {
        load User by actor as learner for update else StudentNotFound;
        load Enrollment by input.id as made for update else EnrollmentNotFound;
        validate made.student == actor else Forbidden;
        load Course by made.course as course for update else CourseNotFound;
        update course when course.enrolled > 0 else EnrollmentCounterMismatch {
          enrolled: course.enrolled - 1;
        }
        persist course;
        delete made;
        return unit;
      }
    }
    // Trusted, append-only transcript facts; no student payload can assert that a prerequisite was passed.
    capability MyEnrollments {
      actor Ref<User>;
      input PageOnly;
      output Page<EnrollmentView>;
      fails BadPage;
      requires authenticated;
      requires readonly;
      expose query at "/enrollments";
      workflow {
        find Enrollment
          where item.student == actor
          order by createdAt descending, id descending
          Page input.page, input.size else BadPage
        as rows;
        return rows;
      }
    }
    // A teacher sees the roster of their own course only.
    input RosterQuery {
      field courseId: Id;
      field page: PageNo;
      field size: PageSize;
    }
    capability Roster {
      actor Ref<User>;
      input RosterQuery;
      output Page<EnrollmentView>;
      fails BadPage;
      fails CourseNotFound;
      fails Forbidden;
      requires authenticated;
      requires readonly;
      expose query at "/courses/{courseId}/roster";
      workflow {
        load Course by input.courseId as course else CourseNotFound;
        validate course.teacher == actor else Forbidden;
        find Enrollment
          where item.course == course
          order by createdAt ascending, id ascending
          Page input.page, input.size else BadPage
        as rows;
        return rows;
      }
    }

    input CreateCourseInput {
      field code: Code;
      field name: Name;
      field teacherId: Id;
      field capacity: Quantity;
      field weekday: Quantity where min(1), max(7);
      field startPeriod: Quantity where min(1), max(12);
      field endPeriod: Quantity where min(1), max(13);
    }
    // Only an administrator may build a course; it starts unpublished with an empty roll.
    capability CreateCourse {
      actor Ref<User>;
      input CreateCourseInput;
      output CourseView;
      fails Forbidden;
      fails InvalidSchedule;
      fails TeacherNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/courses";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        validate input.startPeriod < input.endPeriod else InvalidSchedule;
        load User by input.teacherId as teacher else TeacherNotFound;
        validate teacher.role == Role.TEACHER else TeacherNotFound;
        create Course as built {
          code: input.code;
          name: input.name;
          teacher: teacher;
          capacity: input.capacity;
          weekday: input.weekday;
          startPeriod: input.startPeriod;
          endPeriod: input.endPeriod;
        }
        persist built;
        return built;
      }
    }

    input AddPrerequisiteInput {
      field courseId: Id;
      field requiredId: Id;
    }
    // Direct prerequisites may be added only while the target course is still unpublished.
    capability AddPrerequisite {
      actor Ref<User>;
      input AddPrerequisiteInput;
      output Unit;
      fails CourseNotFound;
      fails CoursePublished;
      fails Forbidden;
      fails InvalidPrerequisite;
      fails PrerequisiteExists;
      requires authenticated;
      requires atomic;
      expose command at "/courses/{courseId}/prerequisites";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        load Course by input.courseId as target for update else CourseNotFound;
        validate target.published == false else CoursePublished;
        load Course by input.requiredId as required else InvalidPrerequisite;
        validate required.published == true else InvalidPrerequisite;
        validate required.id != target.id else InvalidPrerequisite;
        exists Prerequisite where item.targetCourse == target and item.required == required as dup;
        validate not dup else PrerequisiteExists;
        create Prerequisite as link {
          targetCourse: target;
          required: required;
        }
        persist link else PrerequisiteExists;
        return unit;
      }
    }

    input PrerequisiteRef {
      field id: Id;
    }
    // Removing a prerequisite is likewise locked once the target course is published.
    capability RemovePrerequisite {
      actor Ref<User>;
      input PrerequisiteRef;
      output Unit;
      fails CourseNotFound;
      fails CoursePublished;
      fails Forbidden;
      fails PrerequisiteNotFound;
      requires authenticated;
      requires atomic;
      expose command delete at "/prerequisites/{id}";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        load Prerequisite by input.id as link for update else PrerequisiteNotFound;
        load Course by link.targetCourse as target for update else CourseNotFound;
        validate target.published == false else CoursePublished;
        delete link;
        return unit;
      }
    }

    // Publishing is one-way: once published the requirement set is frozen.
    capability PublishCourse {
      actor Ref<User>;
      input CourseRef;
      output CourseView;
      fails CourseNotFound;
      fails CoursePublished;
      fails Forbidden;
      requires authenticated;
      requires atomic;
      expose command at "/courses/{id}/publish";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        load Course by input.id as target for update else CourseNotFound;
        validate target.published == false else CoursePublished;
        update target {
          published: true;
        }
        persist target;
        return target;
      }
    }

    input RecordCompletionInput {
      field studentId: Id;
      field courseId: Id;
    }
    // Only an administrator records a passing grade; the row immediately counts for later enrolments.
    capability RecordCompletion {
      actor Ref<User>;
      input RecordCompletionInput;
      output Unit;
      fails CompletionExists;
      fails CourseNotFound;
      fails Forbidden;
      fails StudentNotFound;
      requires authenticated;
      requires atomic;
      expose command at "/completions";
      workflow {
        validate actor.role == Role.ADMIN else Forbidden;
        load User by input.studentId as learner else StudentNotFound;
        validate learner.role == Role.STUDENT else StudentNotFound;
        load Course by input.courseId as passed for update else CourseNotFound;
        exists CompletedCourse where item.student == learner and item.course == passed as dup;
        validate not dup else CompletionExists;
        create CompletedCourse as record {
          student: learner;
          course: passed;
        }
        persist record else CompletionExists;
        return unit;
      }
    }
  }
}

messages.content:
你为 KCG-Code 生成完整、可静态检查的 SIR 0.3 文档。只返回 SIR 源码，不加 Markdown 围栏、Java、SQL、解释或思维过程。只用下面出现过的写法，不得凭空发明语言构造；拿不准时用已出现的构造组合。

一、文档骨架（固定）
sir 0.3
software 名字 {
  metadata { displayName "名字"; namespace "合同给出的包名"; }
  target { language java 21; framework spring_boot; persistence mybatis_plus; database mysql; build maven; interface rest; }
  sources { }
  imports { }
  declarations { 声明 }
}
保留字不能当实体、字段、变量（as 后面的名字）、错误或能力的名字，最容易撞上的是 item、order、error、input、target、query、command、build、from、field、present；变量可以叫 course、row、made、found 这类普通名字。注释用 //。

二、类型
Id（64 位编号）、Serial（64 位整数）、Version（版本号）、Count（32 位整数）、Quantity（至少 1）、PageNo、PageSize、Money（十进制，默认 precision(19, 2)）、Text、Name（非空白，1～100）、Code（非空白，1～32）、Remark、Email、Secret（口令，只存摘要）、Token（UUID）、Moment（时刻，UTC）、Day（日期）、Flag（布尔）、Unit、Optional<T>、List<T>、Page<T>、Ref<实体>。
可自定义：type UnitPrice = Money where precision(19, 4), min(0);
枚举：enum Status { OPEN, CLOSED }，用时写 Status.OPEN。

三、声明
实体：
entity Course persistent {
  identity id: Id generated auto;
  field code: Code unique;
  field capacity: Quantity;
  field enrolled: Count default 0;
  field note: Optional<Text>;
  field owner: Ref<User>;
}
- 成员顺序固定：identity，所有 field，联合 unique (a, b);（若有），credential（若有），scope（若有）。
- identity 二选一：identity id: Id generated auto; 或 identity id: Token generated uuid;。
- 字段修饰顺序固定：where 约束、versioned、unique、secret、default 值。例如 field name: Name where length(1, 64) unique;（不能写成 unique where …）。约束有 notBlank、email、timeZone、length(最小, 最大)、min(值)、max(值)、precision(总位数, 小数位)。
- default 可以是常量、枚举成员或 now()；带 default 的字段在 create 里可以不写。
- 软删除：field removed: Flag default false; scope removed == false;
- 访问令牌实体：identity id: Token generated uuid; field owner: Ref<User>; field expiresAt: Moment; credential subject owner expires expiresAt;。请求头 Bearer 令牌就是它的主键；刷新令牌不要声明 credential。
- 数据库对应：实体名 TokenPair 对应表 token_pair，字段 accessExpiresAt 对应列 access_expires_at，引用字段 owner 对应列 owner_id。给出了表结构时，实体与字段必须和它一一对应。
输入：input RegisterInput { field name: Name where length(1, 64); field note: Optional<Text>; }。输入字段只有名字、类型和 where 约束，不能写 default。约束（notBlank、length、min 等）只能写在字段声明的 where 里，不是表达式，不能写进 validate；要求非空白就把输入字段写成 field keyword: Text where notBlank;。
分页：输入里写 field page: PageNo; field size: PageSize;，配 find … Page input.page, input.size else 错误。缺省值（页码 1、页大小 20）和上限（页大小 100、页码 10000）由生成器提供，不要自己写。
局部更新输入（实体必须有 Version 字段）：input UpdateCourseInput patch of Course { field id: Id; field name: Text; }，只写主键和允许修改的字段（不写 Version 字段）；patch 字段不能带任何规则，所以用去掉规则的类型：Name、Code、Remark、Email 写成 Text，Quantity 写成 Count，可选的照样写 Optional<Text>；每个 patch 字段在 update 里直接绑定 name: input.name;，客户端没传的字段自动保留原值，不用也不能写条件选择（SIR 没有 ? : 三元表达式）；用 input.name.present 判断传了没有（.present 只能用在 patch of 输入的字段上；普通输入要判断可选值有没有，用 input.x is none 或 is present）（例如至少改一项：validate input.name.present or input.capacity.present else EmptyChange;），update 后写 persist course else StaleVersion;。带 Version 的实体由版本号防并发：不能对它写 update … when 守卫，也不能写“本字段 + 值”的原子加减，版本冲突只靠 persist … else 报错。生成的 PATCH 接口请求体是 {"id": …, "expectedVersion": …, "changes": { 可改字段 }}，外层的 expectedVersion 与 changes 由生成器自动包装，合同里出现这种请求体时也不要把它们写进 input。
视图：view CourseView from Course { field id: Id; field code: Code; field remaining: Count = item.capacity - item.enrolled; field owner: UserSummary; field items: List<ItemView>; }。普通字段读同名实体字段；= 表达式是计算字段；字段类型也可以是另一实体的视图（Ref 指向它），或 List<子视图>（子实体有唯一一个指回本实体的 Ref）；带嵌套视图的结果只能来自分页 find，或 load／create 后 return 的那一行。视图不能读 secret 字段、不能带约束。
跨行计数视图字段：field availableCopies: Serial = count(Copy, book == item and status == CopyStatus.AVAILABLE);（带这种字段的视图只能由 readonly 的 query 返回）
错误：error NotFound http 404;（不写 http 时为 400；只允许 400、401、403、404、409）。401 表示没登录或凭据无效，已登录但无权用 403。

四、能力
capability PublishGoods {
  actor Ref<User>;
  input PublishInput;
  output GoodsView;
  fails GoodsNotFound;
  fails NotSeller;
  requires authenticated;
  requires atomic;
  expose command;
  workflow { 步骤 }
}
- 子句顺序固定：actor → input → output → fails（按错误名字升序，每个一行）→ requires（按 authenticated、atomic、readonly 的顺序）→ expose → workflow。
- output 只能是视图、Ref<实体>、List<Ref<实体>>、Page<视图>、Unit 或一个值类型；工作流用到的每个错误都要写进 fails。
- requires authenticated 必须配 actor Ref<实体>;，工作流里用 actor。有两个及以上写步骤（create、update、persist）必须 requires atomic。expose query 必须 requires readonly，只读能力里不能有 create、update、persist、delete。
- 路由：expose query 是 GET /api/能力名短横线形式，输入作查询参数；expose command 是 POST（patch 输入时是 PATCH），输入是 JSON 体。expose command 后面只能接 put 或 delete（或直接 at），POST 是默认，不能写 post。可自定：expose query at "/notes/{id}"; expose command at "/notes"; expose command put at "/notes/{id}"; expose command delete at "/notes/{id}";。at 后面的路径会自动加 /api 前缀，不要自己写 /api（写成 "/api/notes" 会变成 /api/api/notes）；合同给出的路由正好是 /api/能力名短横线形式时，直接写 expose query; 或 expose command;，不写 at。合同给出的路由必须照写。
- 成功状态码由生成器决定：工作流里只要有 create 步骤（包括循环体里的）就返回 201，否则返回 200。需求要求 200 的接口里不能 create 任何行；要求 201 的接口要真的新建一行。

五、工作流（按顺序执行，以且只以一个 return 结束）
validate 条件 else 错误;
load 实体 by input.id as 变量 else 错误;（按主键加载不写字段名，不能写 by id: …）
load 实体 by 唯一字段名: input.name as 变量 else 错误;
load 实体 by input.id as 变量 for update else 错误;（锁住父行，只用于 requires atomic 的 command，按主键）
find 实体 where item.字段 >= input.x and item.title containsLiteral input.keyword order by 字段 descending, id ascending Page input.page, input.size else BadPage as 变量;
- find 的比较左边必须是 item.字段，右边不读 item；不对列做运算。不带 Page 得 List<Ref<实体>>，带 Page 得 Page<视图>（只用于 expose query）。where true 取全部。
- 可选筛选：input.kind is none or item.kind == input.kind。关联存在：any(Enrollment, course == item and active == true)。只看自己：item.owner == actor。
create 实体 as 变量 { 字段: 值; ... }（给出所有必填字段，不绑主键和 Version）
update 变量 { 字段: 值; }
persist 变量;（create／update 之后都要 persist 才写库。persist 变量 else 错误; 只有两种用法：带 Version 实体的局部更新报版本冲突；新建的行撞上实体的 unique 约束。其他情况只写 persist 变量;，守卫更新后也一样）
update 变量 when 条件 else 错误 { 字段: 值; }（守卫更新：写入时条件仍成立才写，并发下只让一个成功；后面要 persist；绑定值不能读这一行的其它字段）
计数原子加减：update course when course.enrolled < course.capacity else CourseFull { enrolled: course.enrolled + 1; }
delete 变量;（只删 load 出来的行或 each 正在处理的行）
exists 实体 where 条件 as 布尔;　count 实体 where 条件 as 数量;
sum 实体.金额字段 where 条件 as 合计;（只在 readonly query 里；avg 同理）
sum 实体.金额字段 by 引用字段 where 条件 Page input.page, input.size else BadPage as 分组;（输出 Page<SumGroup<Ref<实体>>>）
month input.month in input.zone as since, until else BadPeriod;（只读 query 里，得到当地自然月的起止时刻）
each 实体 where 条件 order by 字段 ascending, id ascending limit 50 else TooMany as 行 { 步骤 }（只在 atomic command；limit 为 1～100 的字面量；体内不能 find、return、嵌套循环）
repeat input.weeks times limit 12 else TooMany as week { 步骤 }
return 变量;（或 return unit;）

六、易错点
- 新建的行在 persist 之前没有主键：先 persist access; 再读 access.id、把 access 当作引用字段的值，或返回含主键的视图（诊断 SIR-FLOW-007）。其他字段 create 后即可读。
- 新建一行并给被引用的行计数时，先 persist 被计数的行，再 persist 新行（SIR-VALID-015），或者加载时用 for update。
- 先 exists／count 检查再插入防不住并发；名额上限用守卫计数，时段不重叠先 for update 锁父行再检查。
- 口令：Secret 字段绑定 input.password 时自动存加盐摘要；只能写 validate account.passwordHash matches input.password else BadLogin;，不能比较、返回或放进视图。账号不存在和口令错误用同一个错误。
- 授权：validate goods.seller == actor else NotSeller;，按角色 validate actor.role == Role.ADMIN else Forbidden;。
- 表达式：+ - * 只在同类型整数或金额间（金额可乘整数），没有除法；now()、now() + 15 minutes、addDays(t, n)、daysBetween(a, b)、max(a, b)、min(a, b)；is none、is present；and、or、not。Optional 值不能参与算术。
- 语言自带功能可以直接 use：use DualTokenLogin { account: User; }（访问令牌、刷新令牌、Login／Refresh／Logout，并给 User 加 loginName 与 password 字段），use Crud { entity: Note; }（Create／Get／List／Update／Delete 五个能力）。用了就不能再手写它展开出的同名声明；行为要偏离标准写法时不用 use，手写全部声明。

